# Generated by curate-skills
# Workflow: wordcount_mapreduce_histogram
# Function: reduce_word_counts

"""Reduce phase of the wordcount MapReduce workflow.

Runs ONCE after every map instance has finished. Discovers all per-rank partial
count files in the S3 folder, sums the counts of each word across every shard,
and writes a single combined word-frequency CSV (header ``word,count``) sorted by
descending count with ties broken alphabetically.
"""

import csv
import json
import os
import re
import tempfile


def _partial_file_pattern(input1: str) -> "re.Pattern":
    """Regex matching the per-rank partial-count basenames, e.g.
    'partial_counts_{rank}.json' -> ^partial_counts_(\\d+)\\.json$."""
    placeholder = "{rank}"
    if placeholder in input1:
        head, _, tail = input1.partition(placeholder)
        return re.compile("^" + re.escape(head) + r"(\d+)" + re.escape(tail) + "$")
    # No placeholder: the name itself is the only file to read.
    return re.compile("^" + re.escape(input1) + "$")


def reduce_word_counts(folder: str, input1: str, output1: str) -> None:
    pattern = _partial_file_pattern(input1)

    # Fan-in: the number of map shards is discovered, never assumed.
    keys = faasr_get_folder_list(prefix=folder)
    basenames = []
    seen = set()
    for key in keys:
        name = str(key).rsplit("/", 1)[-1]
        if pattern.match(name) and name not in seen:
            seen.add(name)
            basenames.append(name)

    def _shard_sort_key(name):
        match = pattern.match(name)
        groups = match.groups() if match is not None else ()
        return (int(groups[0]) if groups else 0, name)

    basenames.sort(key=_shard_sort_key)

    if not basenames:
        message = (
            "reduce_word_counts: no partial count files matching %r found in folder %s "
            "(folder listing: %s)" % (input1, folder, sorted(str(k) for k in keys))
        )
        faasr_log(message)
        raise FileNotFoundError(message)

    faasr_log(
        "reduce_word_counts: merging %d partial count files from folder %s: %s"
        % (len(basenames), folder, ", ".join(basenames))
    )

    tmp_dir = tempfile.gettempdir()
    totals = {}
    merged_tokens = 0

    for name in basenames:
        local_input = os.path.join(tmp_dir, "reduce_in_" + name)
        faasr_get_file(local_file=local_input, remote_folder=folder, remote_file=name)

        with open(local_input, "r", encoding="utf-8") as handle:
            raw = handle.read()

        if not raw.strip():
            message = (
                "reduce_word_counts: partial count file %s in folder %s is empty"
                % (name, folder)
            )
            faasr_log(message)
            raise ValueError(message)

        try:
            partial = json.loads(raw)
        except ValueError as exc:
            message = (
                "reduce_word_counts: partial count file %s in folder %s is not valid JSON: %s"
                % (name, folder, exc)
            )
            faasr_log(message)
            raise ValueError(message)

        if not isinstance(partial, dict):
            message = (
                "reduce_word_counts: partial count file %s in folder %s must contain a "
                "JSON object mapping word -> count, got %s"
                % (name, folder, type(partial).__name__)
            )
            faasr_log(message)
            raise ValueError(message)

        shard_tokens = 0
        for word, count in partial.items():
            if isinstance(count, bool) or not isinstance(count, int):
                message = (
                    "reduce_word_counts: count for word %r in %s is not an integer (%r)"
                    % (word, name, count)
                )
                faasr_log(message)
                raise ValueError(message)
            totals[word] = totals.get(word, 0) + count
            shard_tokens += count

        merged_tokens += shard_tokens
        faasr_log(
            "reduce_word_counts: %s contributed %d distinct words / %d word occurrences"
            % (name, len(partial), shard_tokens)
        )

    if not totals:
        message = (
            "reduce_word_counts: the %d partial count files in folder %s contained no words"
            % (len(basenames), folder)
        )
        faasr_log(message)
        raise ValueError(message)

    # Descending count, ties broken alphabetically by word.
    rows = sorted(totals.items(), key=lambda item: (-item[1], item[0]))

    local_output = os.path.join(tmp_dir, "word_frequencies.csv")
    with open(local_output, "w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["word", "count"])
        for word, count in rows:
            writer.writerow([word, count])

    faasr_put_file(local_file=local_output, remote_folder=folder, remote_file=output1)
    faasr_log(
        "reduce_word_counts: wrote %s with %d distinct words and %d total word occurrences"
        % (output1, len(rows), merged_tokens)
    )
